package cn.gd306.tideenglish.core
import kotlinx.coroutines.test.runTest
import org.junit.Assert.*
import org.junit.Test
class EmailAccountControllerTest {
 private val scope="scope"
 private val exchange=EmailAccountExchange("12345678-1234-4234-8234-123456789012","a@example.com","a".repeat(43),"b".repeat(43),900,2000)
 private class Store:EmailAccountStorage {var s:EmailAccountSession?=null;var uncertain=false;override suspend fun read()=s;override suspend fun save(session:EmailAccountSession){s=session;uncertain=false};override suspend fun clear(){s=null;uncertain=false};override suspend fun markUncertain(){uncertain=true};override suspend fun isUncertain()=uncertain}
 private inner class Service:EmailAccountService {var sent=0;var signedOut=0;var deleted=0;var refreshFails=false;var logoutFails=false;override suspend fun challenge(email:String):EmailAccountChallenge {sent++;return EmailAccountChallenge("12345678-1234-4234-8234-123456789012",300,60)};override suspend fun verify(challengeID:String,code:String)=exchange;override suspend fun refresh(refreshToken:String):EmailAccountExchange {if(refreshFails)throw EmailAccountException(EmailAccountFailure.Transport);return exchange.copy(accessToken="c".repeat(43),refreshToken="d".repeat(43))};override suspend fun signOut(refreshToken:String){signedOut++;if(logoutFails)throw EmailAccountException(EmailAccountFailure.Transport)};override suspend fun delete(session:EmailAccountSession,challengeID:String,code:String){deleted++} }
 @Test fun openingDoesNotSendEmailAndCooldownBlocksDuplicates()=runTest {val service=Service();val c=EmailAccountController(service,Store(),scope,{1000});c.restore();assertEquals(0,service.sent);c.sendCode("a@example.com");c.sendCode("a@example.com");assertEquals(1,service.sent);assertEquals(EmailAccountFailure.RateLimited,c.state.value.failure)}
 @Test fun failedLogoutClearsLocalSessionAndReportsUnconfirmedRevocation()=runTest {val service=Service().apply {logoutFails=true};val store=Store().apply {s=EmailAccountSession.create(exchange,scope,1000)};val c=EmailAccountController(service,store,scope,{1001});c.restore();c.signOut();assertNull(store.s);assertNull(c.state.value.email);assertEquals(EmailAccountFailure.RevocationUnconfirmed,c.state.value.failure)}
 @Test fun uncertainRefreshCannotReuseOldToken()=runTest {val service=Service().apply {refreshFails=true};val store=Store().apply {s=EmailAccountSession.create(exchange,scope,1000)};val c=EmailAccountController(service,store,scope,{1950});c.restore();assertNull(store.s);assertNull(c.state.value.email);assertEquals(EmailAccountFailure.RenewalUncertain,c.state.value.failure)}
 @Test fun deletionRequiresNewChallengeAndPreservesAccountUntilCodeVerified()=runTest {val service=Service();val store=Store().apply {s=EmailAccountSession.create(exchange,scope,1000)};val c=EmailAccountController(service,store,scope,{1001});c.restore();c.verify("123456");assertEquals(0,service.deleted);assertNotNull(store.s);c.sendCode("ignored",true);assertTrue(c.state.value.deleting);assertNotNull(store.s);c.verify("123456");assertEquals(1,service.deleted);assertNull(store.s);assertNull(c.state.value.email)}
 @Test fun changingEmailInvalidatesPriorChallenge()=runTest {val service=Service();val store=Store();val c=EmailAccountController(service,store,scope,{1000});c.sendCode("a@example.com");c.invalidateChallenge();c.verify("123456");assertNull(store.s);assertEquals(EmailAccountFailure.InvalidCode,c.state.value.failure)}
 @Test fun reopeningExpiredSessionClearsPreviouslyShownIdentity()=runTest {var time=1001L;val store=Store().apply {s=EmailAccountSession.create(exchange,scope,1000)};val c=EmailAccountController(Service(),store,scope,{time});c.restore();assertNotNull(c.state.value.email);time=4000;c.restore();assertNull(c.state.value.email);assertNull(store.s)}
 @Test fun persistedIntentPreventsRestoringPriorSession()=runTest {val store=Store().apply {s=EmailAccountSession.create(exchange,scope,1000);uncertain=true};val c=EmailAccountController(Service(),store,scope,{1001});c.restore();assertNull(store.s);assertNull(c.state.value.email)}
}
